input.sparql:
SELECT ?p ?pc ?ts WHERE {
  ?p a brick:Electric_Power ;
     rdfs:label ?label .
  ?ts ref:hasTimeseriesId ?id .
  ?p ref:hasTimeseriesId ?id .
}

SELECT ?p ?class ?label WHERE {
  ?p a * brick:Electric_Power .
  ?p rdfs:label ?label .
  ?p a ?class .
}

SELECT ?p ?class ?label WHERE {
  ?p a * brick:Electric_Power
  OPTIONAL { ?p rdfs:label ?label }
  ?p a ?class
}

SELECT ?p ?label ?class ?has WHERE {
  VALUES ?class { brick:Building_Electrical_Meter brick:Electric_Power_Sensor }
  ?p a ?class .
  OPTIONAL { ?p rdfs:label ?label }
  OPTIONAL { ?p ref:hasTimeseriesId ?has }
}
